// Isolated interaction prototype. No filesystem, model, or network operations.
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const old='Academic writing often requires multiple rounds of revision. Existing tools focus on grammar checking or content generation. A clear review process is useful for authors.';
const revisions=[
 'Academic writing involves repeated revisions to arguments, structure, and expression. A review process that separates proposed changes from the accepted manuscript helps authors inspect each revision before adoption.',
 'Academic writing involves revising arguments, evidence, and expression across multiple drafts. Separating proposed changes from the accepted manuscript allows authors to inspect the rendered result, review the rationale, and decide which revisions to adopt.'
];
let tasks=[{id:1,title:'让引言更具体',where:'第 1 页 · Introduction',status:'review',version:2,texts:[...revisions]}, {id:2,title:'补充方法说明',where:'第 2 页 · Methods',status:'review',version:1,texts:['Each proposed revision is prepared independently and reviewed before it becomes part of the manuscript.']},{id:3,title:'统一图表引用',where:'全文 · 图表',status:'done',version:1,texts:['Figure 1 illustrates the review workflow. Table 1 lists the stages of the process.']}];
let state={view:'修改',filter:'review',task:1,tab:'论文效果',file:'main.tex',accepted:old,selected:new Set(['main.tex','sections/introduction.tex','references.bib','figures/workflow.svg','tables/overview.csv']),history:[{label:'统一图表引用',text:old,time:'今天 14:20',files:'main.tex、figures/workflow.svg、tables/overview.csv'}],historyIndex:0};
const files=['main.tex','sections/introduction.tex','references.bib','figures/workflow.svg','tables/overview.csv','README.md'];
const task=()=>tasks.find(t=>t.id===state.task);
const current=()=>task()?.texts[task().version-1]||old;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html){$('#modal').innerHTML=html;$('#dialog').showModal()}
function fileButtons(){return files.map(f=>`${f.includes('/')?`<div class="folder">${f.split('/')[0]}/</div>`:''}<button class="file ${state.file===f&&state.view==='阅读'?'active':''}" data-file="${f}"><span class="symbol">${f.includes('/')?'└':'▫'}</span>${f.includes('/')?f.split('/').at(-1):f}</button>`).join('')}
function sidebar(){let top='';if(state.view==='修改'){top=`<h2>修改任务</h2><div class="filters">${[['review','待审阅'],['done','已完成'],['archive','归档']].map(([id,label])=>`<button data-filter="${id}" class="${state.filter===id?'active':''}">${label} ${tasks.filter(t=>t.status===id).length}</button>`).join('')}</div><div>${tasks.filter(t=>t.status===state.filter).map(t=>`<button class="task ${state.task===t.id?'active':''}" data-task="${t.id}"><strong>${escape(t.title)}</strong><small>${t.where}</small></button>`).join('')||'<div class="empty">这里暂时没有任务</div>'}</div>`}else if(state.view==='版本'){top=`<h2>论文版本</h2><div class="timeline">${state.history.map((h,i)=>`<button data-history="${i}" class="${i===state.historyIndex?'active':''}">${escape(h.label)}<p class="hint">${h.time} · 本地已保存</p></button>`).join('')}</div>`}else if(state.view==='GitHub'){top='<h2>项目同步</h2><p class="hint" style="padding:0 10px">整个项目一起管理。<br>检查范围后，再手动同步。</p>'}else{top='<h2>论文项目</h2><p class="hint" style="padding:0 10px">Paper Studio<br>正文、参考文献与素材</p>'}$('#sidebar').innerHTML=top+`<section class="files"><h2>项目文件</h2>${fileButtons()}</section><div class="branch">⑂ main · 示例项目</div>`}
function paper(text,after=false,interactive=false){return `<article class="paper ${after?'after':''}"><h2>Collaborative Paper Revision</h2><div class="author">An illustrative manuscript · Design preview</div><h3>Abstract</h3><p>This fictional manuscript demonstrates a paper review workflow. It is used to explore how authors inspect suggestions, compare versions, and organize project files. No experimental findings are reported.</p><h3>1 &nbsp; Introduction</h3><p><mark ${interactive?'tabindex="0" role="button" data-annotation="1" aria-label="查看引言批注"':''}>${escape(text)}</mark></p><p>In this example, the manuscript, bibliography, figures, and tables belong to one project. The author retains control over which changes become part of the accepted version.</p><h3>2 &nbsp; Methods</h3><p>Each suggestion is reviewed in context. A preview makes the proposed change visible before the author decides whether to adopt it.</p><h3>3 &nbsp; Project resources</h3><p>Figure 1 shows the review workflow. Table 1 summarizes the stages. The bibliography is maintained separately from the manuscript.</p><div class="pageno">1</div></article>`}
function heading(title,sub,actions=''){return `<section class="heading"><div><h1>${escape(title)}</h1><p>${escape(sub)}</p></div><div class="actions">${actions}</div></section>`}
function compare(a,b,label='修改后预览'){return `<div class="compare"><section class="column"><div class="label">当前论文 <span>正式版本</span></div><div class="paper-scroll" data-sync="left">${paper(a)}</div></section><section class="column"><div class="label">${label} <span>示意排版 · 非实际编译</span></div><div class="paper-scroll" data-sync="right">${paper(b,true)}</div></section></div>`}
function review(){const t=task();if(!t||t.status!==state.filter)return heading('修改任务','从左侧选择任务')+'<div class="empty">当前分类没有选中的任务。</div>';let status=t.status==='done'?'已采纳 · 已保存本地版本':t.status==='archive'?'已归档 · 历史仍保留':'尚未写入论文';let html=heading(t.title,`${t.where} · ${status}`,`<select id="version" aria-label="建议版本">${t.texts.map((_,i)=>`<option value="${i+1}" ${t.version===i+1?'selected':''}>第 ${i+1} 版</option>`).join('')}</select><button data-action="archive">${t.status==='archive'?'恢复任务':'归档'}</button>`);
html+=`<div class="tabs">${['论文效果','修改说明','AI 回复'].map(x=>`<button data-tab="${x}" class="${state.tab===x?'active':''}">${x}</button>`).join('')}</div><div class="canvas">`;
if(state.tab==='论文效果')html+=compare(state.accepted,current());
if(state.tab==='修改说明')html+=`<div class="prose"><h2>修改了什么，为什么修改</h2><p class="hint">示例说明 · 第 ${t.version} 版</p><h3>原文</h3><div class="excerpt">${escape(old)}</div><h3>建议文字</h3><div class="excerpt after">${escape(current())}</div><h3>修改原因</h3><ul><li>将笼统的“多轮修改”具体化为论证、证据和表达三个方面。</li><li>说明作者可以检查论文效果、阅读原因，再决定是否采纳。</li><li>不新增实验结论，也不添加未经核实的引用。</li></ul><details><summary>源码详情 · 需要时查看</summary><pre>sections/introduction.tex\n\n${escape(current())}</pre></details></div>`;
if(state.tab==='AI 回复')html+=`<div class="prose"><h2>AI 回复</h2><p class="hint">样稿中的虚构回复。正式接入时，此处保留模型实际返回的内容；不展示或编造内部思考过程。</p><div class="raw">我会保留原段落的核心含义，让研究对象和作者的操作更具体。\n\n建议改为：\n${escape(current())}\n\n修改说明：\n1. 明确修改涉及论证、证据与表达。\n2. 补充作者检查预览、理解修改理由与决定采纳的流程。\n3. 保持示例性质，没有加入新的研究结论。${t.feedback?'\n\n本轮补充要求：'+escape(t.feedback):''}</div></div>`;
html+=`</div><footer class="foot"><span class="muted">${t.status==='review'?'仅在采纳后更新正式论文':'历史记录保留，可随时查看'} · 样稿操作</span><div class="actions"><button data-action="feedback">继续修改</button><button class="primary" data-action="adopt" ${t.status!=='review'?'disabled':''}>${t.status==='done'?'已采纳':'采纳此版本'}</button></div></footer>`;return html}
function reading(){let html=heading(state.file==='main.tex'?'阅读论文':state.file,'示例项目 · 点击左侧文件可预览关联资源',`<button data-action="newtask">新建修改</button>`);if(state.file==='main.tex'||state.file.endsWith('.tex'))return html+`<div class="canvas"><div class="reading">${paper(state.accepted,false,true)}</div></div><footer class="foot"><span class="muted">点击高亮查看批注 · 这里的论文排版为交互示意</span><button data-action="translation">翻译示例</button></footer>`;
if(state.file.endsWith('.bib'))html+='<div class="canvas"><div class="prose"><h2>参考文献库</h2><p class="hint">references.bib · 示例条目</p><table><thead><tr><th>引用键</th><th>文献</th><th>状态</th></tr></thead><tbody><tr><td>demo2026</td><td>A Demonstration of Collaborative Revision</td><td>虚构示例</td></tr></tbody></table><p>正式版将展示文献标题、作者、年份和引用情况。</p></div></div>';
else if(state.file.endsWith('.svg'))html+='<div class="canvas"><div class="asset"><div class="diagram"><div>提出批注</div><span class="arrow">→</span><div>审阅预览</div><span class="arrow">→</span><div>确认采纳</div></div></div><p class="hint">Figure 1 · 示例流程图 · 随项目一起管理</p></div>';
else if(state.file.endsWith('.csv'))html+='<div class="canvas"><div class="prose"><h2>Table 1 · Review stages</h2><table><thead><tr><th>阶段</th><th>正文状态</th><th>负责人</th></tr></thead><tbody><tr><td>生成建议</td><td>不变</td><td>Kimi</td></tr><tr><td>检查预览</td><td>不变</td><td>作者</td></tr><tr><td>确认采纳</td><td>更新并保存版本</td><td>作者</td></tr></tbody></table></div></div>';
else html+='<div class="canvas"><div class="prose"><h2>Paper Studio</h2><p>这是用于界面设计的虚构论文项目。</p><p>正文、参考文献、图片、表格和协作说明共同组成项目。</p></div></div>';return html}
function versions(){const h=state.history[state.historyIndex];return heading('论文版本',`${h.time} · ${h.label}`)+`<div class="canvas"><p class="hint">此版本关联文件：${escape(h.files)}</p><div class="reading">${paper(h.text)}</div></div><footer class="foot"><span class="muted">正式版本与未采纳建议分开保存</span><button data-action="historyfiles">查看版本文件</button></footer>`}
function github(){return heading('GitHub 协作','Paper Studio · 整个项目 · 演示，无网络操作')+`<div class="canvas"><div class="prose"><div class="git-head"><div><h2>准备同步的项目文件</h2><p class="hint">分支 main · 示例远端 paper-studio</p></div><button data-action="remote">检查协作者更新</button></div><table><thead><tr><th>包含</th><th>文件</th><th>内容</th></tr></thead><tbody>${files.map((f,i)=>`<tr><td><input type="checkbox" data-check="${f}" aria-label="包含 ${f}" ${state.selected.has(f)?'checked':''}></td><td>${f}</td><td>${['论文入口','章节正文','参考文献','图片','表格数据','项目说明'][i]}</td></tr>`).join('')}</tbody></table><details><summary>排除的文件（3）</summary><p class="hint">main.aux · main.log · 私有设置<br>正式版需按项目规则核对完整文件清单，不能仅靠扩展名决定上传范围。</p></details><div class="formrow"><label for="commit">版本说明</label><input id="commit" type="text" placeholder="例如：完善引言与流程图"></div><div class="notice">本地保存和 GitHub 同步分开。同步前查看文件范围；遇到协作者更新时，先比较差异。</div></div></div><footer class="foot"><span class="muted">已选择 ${state.selected.size} 个文件 · 仅演示，不上传</span><button class="primary" data-action="sync" ${!state.selected.size?'disabled':''}>检查并同步…</button></footer>`}
function render(){ $('#nav').innerHTML=['阅读','修改','版本','GitHub'].map(n=>`<button data-view="${n}" class="${state.view===n?'active':''}" aria-current="${state.view===n?'page':'false'}">${n}</button>`).join('');sidebar();$('#main').innerHTML=({阅读:reading,修改:review,版本:versions,GitHub:github}[state.view])();const panes=[...document.querySelectorAll('[data-sync]')];panes.forEach((p,i)=>p.addEventListener('scroll',()=>{const other=panes[1-i];const a=p.scrollHeight-p.clientHeight,b=other.scrollHeight-other.clientHeight;if(a>0&&b>0&&Math.abs(other.scrollTop-p.scrollTop/a*b)>2)other.scrollTop=p.scrollTop/a*b},{passive:true}))}
function selectTask(id){state.task=Number(id);state.view='修改';state.filter=task().status;state.tab='论文效果';render()}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-annotation]');if(!b)return;const d=b.dataset;if(d.view){state.view=d.view;render()}if(d.filter){state.filter=d.filter;state.task=tasks.find(t=>t.status===d.filter)?.id;render()}if(d.task)selectTask(d.task);if(d.annotation)selectTask(d.annotation);if(d.tab){state.tab=d.tab;render()}if(d.file){state.file=d.file;state.view='阅读';render()}if(d.history){state.historyIndex=Number(d.history);render()}if(d.action)actions[d.action]?.()});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-annotation]')&&['Enter',' '].includes(e.key)){e.preventDefault();selectTask(e.target.dataset.annotation)}});
document.addEventListener('change',e=>{if(e.target.id==='version'){task().version=Number(e.target.value);render()}if(e.target.dataset.check){e.target.checked?state.selected.add(e.target.dataset.check):state.selected.delete(e.target.dataset.check);const input=$('#commit')?.value;render();$('#commit').value=input||''}});
$('#toggle').onclick=()=>document.body.classList.toggle('hide');$('#model').onchange=()=>toast('模型选择仅在样稿中生效');
const actions={
archive(){const t=task();if(t.status==='archive'){t.status=t.previousStatus||'review';state.filter=t.status}else{t.previousStatus=t.status;t.status='archive';state.filter='archive'}render();toast(t.status==='archive'?'任务已归档，回复和版本仍然保留':'任务已恢复')},
adopt(){modal(`<h2>采纳第 ${task().version} 版？</h2><p>此操作在样稿中更新论文效果，并新增一条本地版本记录。</p><p class="hint">真实论文文件不会改变。</p><div class="actions"><button onclick="document.querySelector('dialog').close()">返回审阅</button><button class="primary" id="confirm-adopt">确认采纳（演示）</button></div>`);$('#confirm-adopt').onclick=()=>{state.accepted=current();task().status='done';state.filter='done';state.history.unshift({label:task().title,text:current(),time:'刚刚',files:'main.tex、sections/introduction.tex、references.bib、figures/workflow.svg、tables/overview.csv'});state.historyIndex=0;$('#dialog').close();render();toast('演示采纳完成，可在“版本”中查看')}} ,
feedback(){modal('<h2>继续修改</h2><p>保留当前版本，补充你的要求。</p><label for="feedback">修改要求</label><textarea id="feedback" placeholder="例如：更简洁，并保留证据与表达这两个重点"></textarea><p class="hint">样稿将添加一个示例版本，不调用模型。</p><button class="primary" id="send-feedback">生成下一版（演示）</button>');$('#send-feedback').onclick=()=>{const text=$('#feedback').value.trim();if(!text){$('#feedback').focus();return}const t=task();t.feedback=text;t.texts.push('Authors revise arguments, evidence, and expression across drafts. Reviewing each proposed change before adoption keeps the manuscript under the author’s control.');t.version=t.texts.length;t.status='review';state.filter='review';$('#dialog').close();render();toast('示例新版已生成，旧版保留')}} ,
newtask(){modal('<h2>新建修改</h2><label for="request">你希望如何修改论文？</label><textarea id="request" placeholder="输入修改要求"></textarea><div class="formrow"><label for="mode">处理方式 </label><select id="mode"><option>立即处理</option><option>先保存，稍后批量处理</option></select></div><button class="primary" id="create-task">添加示例任务</button>');$('#create-task').onclick=()=>{const text=$('#request').value.trim();if(!text){$('#request').focus();return}const id=Date.now();tasks.push({id,title:text,where:'全文 · 示例任务',status:'review',version:1,texts:[revisions[0]]});$('#dialog').close();selectTask(id);toast('已添加示例任务；正式模型与队列尚未接入')}} ,
translation(){modal('<h2>划选翻译</h2><p class="hint">浮窗内容示意 · 未调用翻译 API</p><p>学术写作需要在多个草稿之间反复调整论证、证据和表达。将建议与正式稿分开，作者可以检查预览、理解原因，再决定是否采纳。</p><button id="to-review">查看这段的修改建议</button>');$('#to-review').onclick=()=>{$('#dialog').close();selectTask(1)}},
historyfiles(){modal(`<h2>此版本的项目文件</h2><p class="hint">${escape(state.history[state.historyIndex].label)} · 示例快照</p>${files.map(f=>`<p>${f}</p>`).join('')}`)},
remote(){modal('<h2>协作者有新的修改</h2><p>演示情景：协作者更新了 references.bib，你的引言修改保留在本地。</p><table><tr><th>远端新增</th><td>references.bib</td></tr><tr><th>本地待同步</th><td>sections/introduction.tex</td></tr></table><p class="hint">正式版应先检查能否合并；同一处冲突时展示双方内容，由你决定。此样稿没有读取远端。</p>')},
sync(){const selected=[...state.selected];const note=$('#commit').value.trim();modal(`<h2>确认同步范围</h2><p>${selected.length} 个文件 · main → 示例远端</p><p class="hint">${escape(note||'未填写版本说明')}</p>${selected.map(f=>`<p>${f}</p>`).join('')}<button class="primary" id="mock-sync">完成同步演示</button>`);$('#mock-sync').onclick=()=>{$('#dialog').close();toast('同步流程演示结束。没有上传任何文件。')}}
};render();
